fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    assert!(len > 0, "Input list must be non-empty"); // Just a sanity check.

    let rot = n % len;
    let s = len - rot;

    // Create a new vector with capacity len
    let mut new_list = Vec::with_capacity(len);

    // Append suffix from s to len
    new_list.extend_from_slice(&list[s..len]);

    // Append prefix from 0 to s
    new_list.extend_from_slice(&list[0..s]);

    new_list
}